function rng(seed){let n=seed*9301+49297;return()=>{n=(n*9301+49297)%233280;return n/233280}}
function shuffled(arr,seed){const a=[...arr],r=rng(seed);for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function dayTasks(day){const pool=day<=10?['find','match','purpose','color','count','choice']:day<=20?['find','match','purpose','color','count','choice','shape','odd']:day<=30?['find','match','purpose','color','count','choice','shape','odd','sort','puzzle','life','sorter','pyramid','tower','beads']:types.map(t=>t[0]);const all=[];for(let i=0;i<8;i++){let type=pool[(day*5+i*7)%pool.length];if(state.excluded.includes(type)){const allowed=types.filter(t=>!state.excluded.includes(t[0]));type=allowed[(day+i)%allowed.length]?.[0]||'find'}const id=`d${day}-t${i}`;const previous=state.completed[id]?.type;if(previous&&types.some(t=>t[0]===previous)&&!state.excluded.includes(previous))type=previous;all.push({id,day,index:i,type,seed:day*71+i*37})}return all}
function getTaskTitle(t){return types.find(x=>x[0]===t.type)?.[1]||'Занятие'}
function taskArt(t){return types.find(x=>x[0]===t.type)?.[2]||8}
function doneDay(d){return dayTasks(d).filter(t=>state.completed[t.id]).length}
