function header(){return `<header class="topbar"><div class="brand"><span class="brandmark" aria-hidden="true">✦</span><div>Мой мир<small>играю и расту</small></div></div><div class="options-row"><button class="utility" data-action="gate" aria-label="Настройки для родителей">${svg('gear')}<span>Для родителей<span class="settings-word"> · настройки</span></span>${svg('lock')}</button></div></header>`}
function pageHead(title,sub='',extra=''){return `<div class="page-head"><div class="page-title"><h1>${title}</h1><p>${sub}</p></div><button class="back" data-action="home">← На главную</button></div>${extra}`}
function render(){clearTimeout(memoryTimer);applySettings();$('#app').innerHTML=`<main class="shell">${header()}${views[route]?views[route]():homeView()}<p class="footnote">В своём темпе. С интересом. Каждый маленький шаг важен.</p></main>`;if(route==='game')afterGameRender()}
function navigate(next){if(window.MoyMirNative)MoyMirNative.stop();if('speechSynthesis'in window)speechSynthesis.cancel();route=next;feedback='';hinted=false;render();window.scrollTo({top:0,behavior:'instant'})}
function homeView(){const tasks=dayTasks(state.day);return `<section class="welcome"><div><h1 class="hello ${state.name.length>12?'long-name':''}">Привет${state.name?`, <em>${h(state.name)}</em>`:''}!</h1><p>Что будем делать сегодня?</p></div><button class="round" data-action="greet" aria-label="Прослушать приветствие">${svg('sound')}</button></section><section class="quick-answers" aria-label="Мой ответ"><button class="quick-answer yes" data-action="quick-answer" data-answer="Да" aria-label="Да"><span class="quick-symbol" aria-hidden="true">✓</span>Да</button><button class="quick-answer no" data-action="quick-answer" data-answer="Нет" aria-label="Нет"><span class="quick-symbol" aria-hidden="true">×</span>Нет</button></section><section class="home-grid" aria-label="Мои разделы">${sections.map(([key,title,sub,color,a,b])=>`<button class="tile ${color}" data-action="nav" data-route="${key}">${b!==undefined?`<span class="duo">${art(a)}${art(b)}</span>`:art(a)}<span class="tile-title">${title}</span><span class="tile-sub">${sub}</span></button>`).join('')}</section><section class="daily"><div class="daily-heading"><div><span class="eyebrow">Маленькие открытия</span><h2>Сегодняшние<br class="desktop-br"> занятия</h2></div><span class="daypill"><span class="dot"></span> День ${state.day} · ${doneDay(state.day)} из 8</span></div><div class="daily-list">${tasks.map(t=>`<button class="mini" data-action="task" data-index="${t.index}">${taskVisual(t)}${state.completed[t.id]?'<span class="done-badge">✓</span>':''}${getTaskTitle(t)}</button>`).join('')}</div></section>${activeTask?`<div class="toolbar" style="justify-content:center;margin-top:22px"><button class="secondary" data-action="resume">Продолжить: ${getTaskTitle(activeTask)}</button></div>`:''}`}
function communicateView(kind){let list=kind==='wants'?wants:emotions;return pageHead(kind==='wants'?'Я хочу':'Мои эмоции',kind==='wants'?'Выбери карточку — я помогу сказать.':'Любые чувства важны. Как ты сейчас?')+`<div class="cards">${list.map(([label,a,c],i)=>`<button class="tile ${c||['yellow','orange','pink','purple','green','blue'][i%6]}" data-action="say" data-kind="${kind}" data-index="${i}">${art(a)}<span class="tile-title">${label}</span></button>`).join('')}${kind==='wants'?state.custom.map((c,i)=>`<button class="tile blue" data-action="custom-say" data-index="${i}"><img class="custom-art" src="${h(c.image)}" alt=""><span class="tile-title">${h(c.label)}</span></button>`).join(''):''}</div>`}
function skillsView(){return pageHead('Я могу','Учимся по шагам. Можно попросить взрослого помочь.')+`<div class="cards">${skillData.map(([name,a],i)=>`<button class="tile ${['green','blue','yellow','purple'][i%4]}" data-action="skill" data-index="${i}">${state.skills.includes(i)?'<span class="badge-skill">✓</span>':''}${art(a)}<span class="tile-title">${name}</span></button>`).join('')}</div>`}
function scheduleView(){const checked=state.checked[today()]||[];return pageHead('Мой день','Нажми на галочку, когда закончишь. Порядок можно менять со взрослым.')+`<section class="panel schedule">${state.schedule.map(([time,label,a],i)=>`<div class="schedule-row ${checked.includes(i)?'done':''}"><span class="time">${h(time)}</span>${art(a)}<strong>${h(label)}</strong><button class="round" data-action="read-schedule" data-index="${i}" aria-label="Озвучить: ${h(label)}">${svg('sound')}</button><button class="check" data-action="schedule-check" data-index="${i}" aria-label="${checked.includes(i)?'Снять отметку':'Завершить'}: ${h(label)}" aria-pressed="${checked.includes(i)}">${checked.includes(i)?'✓':''}</button></div>`).join('')}</section>`}
function achievementsView(){const n=Object.keys(state.completed).length;return pageHead('Мои достижения','У каждого свой путь. Здесь — твои открытия.')+`<div class="stats"><div class="panel stat">${art(7)}<strong>${n}</strong><p>занятий выполнено</p></div><div class="panel stat">${art(5)}<strong>${state.skills.length}</strong><p>навыков освоено</p></div><div class="panel stat">${art(13)}<strong>${new Set(Object.values(state.completed).map(x=>x.day)).size}</strong><p>дней с открытиями</p></div></div><section class="panel"><h2>Мои навыки</h2>${state.skills.length?`<div class="options-row">${state.skills.map(i=>`<span class="completed-mark">✓ ${skillData[i][0]}</span>`).join('')}</div>`:'<p class="empty">Пробуй, исследуй, учись.<br>Освоенные навыки взрослый отметит в разделе «Я могу».</p>'}</section><section class="panel"><h2>Последние открытия</h2>${state.history.length?state.history.slice(-15).reverse().map(item=>`<div class="history-row"><span>${h(item.title)}</span><span>${h(item.date)}</span></div>`).join(''):'<p class="empty">Здесь появятся твои выполненные занятия.</p>'}</section>`}
function activitiesView(){const tasks=dayTasks(state.day),count=doneDay(state.day);return pageHead('Мои занятия','Выбирай день или любимую игру. Все занятия открыты.')+`<section class="panel"><h2>Игры руками</h2><p class="settings-note">Перетаскивай детали или выбирай их нажатием.</p><div class="activity-list">${TOY_TYPES.filter(type=>!state.excluded.includes(type)).map(type=>`<button class="mini" data-action="free-game" data-type="${type}">${toyIcon(type)}${types.find(t=>t[0]===type)[1]}</button>`).join('')}</div></section><section class="panel"><div class="route-banner"><div><span class="eyebrow">Моя программа · 60 дней и дальше</span><h2>День ${state.day}</h2><p class="board-sub">${count} из 8 занятий выполнено · можно остановиться в любой момент</p></div>${art(6)}</div><div class="progress-track"><div class="progress-fill" style="width:${count/8*100}%"></div></div><div class="toolbar" style="margin-top:20px"><button class="primary" data-action="start-day">${count===8?'Повторить день':'Начать занятия'}</button><button class="secondary" data-action="choose-day">Выбрать день</button>${state.day>=60?'<button class="secondary" data-action="next-day">Следующий день →</button><button class="secondary" data-action="reset-program">Для родителя: начать заново</button>':''}</div><div class="activity-list">${tasks.map(t=>`<button class="mini" data-action="task" data-index="${t.index}">${taskVisual(t)}${getTaskTitle(t)}${state.completed[t.id]?'<br><span class="completed-mark">Готово</span>':''}</button>`).join('')}</div></section><section class="panel"><h2>Любимые игры</h2><p class="settings-note">Можно повторять столько, сколько хочется.</p><div class="activity-list">${types.filter(x=>!state.excluded.includes(x[0])&&!TOY_TYPES.includes(x[0])).map(([type,title,a])=>`<button class="mini" data-action="free-game" data-type="${type}">${TOY_TYPES.includes(type)?toyIcon(type):art(a)}${title}</button>`).join('')}</div></section>`}
function level(t){if(state.level!=='auto')return Number(state.level);const recent=state.history.slice(-8);let base=t.day<=10?2:t.day<=40?3:4;if(recent.length>=4&&recent.filter(x=>x.errors>1).length>3)base=2;return base}
function prepareTask(t){const n=level(t),r=rng(t.seed),target=t.seed%objects.length;let options=shuffled([...Array(16).keys()].filter(x=>x!==target),t.seed).slice(0,n-1);options=shuffled([target,...options],t.seed+8);let data={...t,n,target,options};
 if(t.type==='color'){data.target=t.seed%colors.length;data.options=shuffled([data.target,...shuffled([0,1,2,3,4].filter(x=>x!==data.target),t.seed).slice(0,n-1)],t.seed+8)}
 if(t.type==='shape'){data.target=t.seed%shapes.length;data.options=shuffled([data.target,...shuffled([0,1,2,3,4].filter(x=>x!==data.target),t.seed).slice(0,n-1)],t.seed+8)}
 if(t.type==='count'){data.target=1+t.seed%(t.day<11?3:t.day<31?5:10);data.options=shuffled([data.target,...shuffled([...Array(t.day<11?3:10)].map((_,i)=>i+1).filter(i=>i!==data.target),t.seed).slice(0,n-1)],t.seed+3)}
 if(t.type==='purpose'){let p=[['Из чего пьют?',0],['На чём можно спать?',12],['Чем можно играть?',3],['Что можно съесть?',1],['Чем можно помыться?',11]];const chosen=p[t.seed%p.length];data.prompt=chosen[0];data.target=chosen[1];data.options=shuffled([data.target,...shuffled([0,12,3,1,11].filter(x=>x!==data.target),t.seed).slice(0,n-1)],t.seed+8)}
 if(t.type==='sequence'){data.pair=shuffled([0,1,2,3,8,13,15],t.seed).slice(0,t.day>30?3:2);data.target=data.pair[0];data.options=shuffled([data.target,...shuffled([0,1,2,3,8,13,15].filter(x=>x!==data.target),t.seed+1).slice(0,n-1)],t.seed+8)}
 if(t.type==='odd'){data.base=t.seed%4;data.target=(data.base+1)%4;data.oddPos=t.seed%n;data.options=Array.from({length:n},(_,i)=>i===data.oddPos?data.target:data.base)}
 if(t.type==='sort'){data.groups=shuffled([0,1,2,3,4],t.seed).slice(0,n===2?2:3);data.items=shuffled([...data.groups,...data.groups],t.seed+3)}
 if(t.type==='life'){data.skill=t.seed%4;data.steps=skillData[data.skill][2];data.stepsArt=skillData[data.skill][3];data.options=shuffled([0,1,2],t.seed);if(data.options.every((x,i)=>x===i))data.options=[1,0,2]}
 return data}
let gameData=null;
function instruction(d){switch(d.type){case'sorter':return 'Разложи фигуры в сортер';case'pyramid':return 'Собери пирамидку';case'tower':return 'Построй башню';case'beads':return 'Собери бусы';case'find':return 'Найди '+objects[d.target][0];case'color':return 'Найди '+colors[d.target][0]+' кубик';case'shape':return 'Найди '+shapes[d.target][0];case'purpose':return d.prompt;case'count':return 'Сколько яблок?';case'memory':return memoryHidden?'Какой предмет ты запомнил?':'Запомни предмет';case'match':return 'Найди такой же предмет';case'odd':return 'Найди фигуру, которая отличается';case'sequence':return 'Продолжи ряд';case'sort':return 'Разложи кубики по цвету';case'puzzle':return 'Собери картинку';case'life':return 'Что сначала? Что потом?';case'choice':return 'Что ты выбираешь?';default:return 'Давай поиграем'}}
function startTask(t){activeTask={...t};state.task=activeTask;persist();gameData=prepareTask(t);initializeToy(gameData);feedback='';hinted=false;errors=0;success=false;orderPicked=[];sortPicked=null;sorted=[];pieceSelected=null;memoryHidden=false;puzzle=shuffled([...Array(level(t)===2?2:t.day>30?6:4).keys()],t.seed);if(puzzle.every((x,i)=>x===i))puzzle.reverse();navigate('game');speak(`${state.name}, ${instruction(gameData).toLowerCase()}`)}
function shape(type,color){return `<span class="shape ${type}" style="--scolor:${color}" aria-hidden="true"></span>`}
function optionVisual(d,value){if(d.type==='color')return shape('square',colors[value][1]);if(d.type==='shape')return shape(shapes[value][1],colors[(d.seed+value)%5][1]);if(d.type==='odd')return shape(shapes[value][1],colors[d.seed%5][1]);if(d.type==='count')return `<span style="font-size:44px;padding:25px">${value}</span>`;return art(value)}
function gameView(){if(!gameData&&activeTask)gameData=prepareTask(activeTask);const d=gameData;if(!d)return activitiesView();let body='';const title=instruction(d);
 if(TOY_TYPES.includes(d.type)){body=toyView(d)}
 else if(d.type==='memory'&&!memoryHidden&&!success){body=`<div style="text-align:center">${art(d.target)}<p class="task-caption">Посмотри внимательно. Нажми, когда будешь готов.</p><button class="primary" data-action="memory-hide">Я запомнил</button></div>`}
 else if(d.type==='sort'){body=`<p class="task-caption" style="text-align:center">Сначала нажми на кубик, затем на корзинку такого же цвета.</p><div class="answers">${d.items.map((v,i)=>sorted.includes(i)?'':`<button class="answer ${sortPicked===i?'selected':''}" style="min-width:80px;min-height:110px;flex:none" data-action="sort-pick" data-index="${i}" aria-label="${colors[v][0]} кубик">${shape('square',colors[v][1])}</button>`).join('')}</div><div class="answers">${d.groups.map(v=>`<button class="answer" style="border:5px solid ${colors[v][1]};min-height:110px" data-action="sort-drop" data-value="${v}"><span style="font-size:16px">${colors[v][0]}<br>корзинка</span><span style="font-size:26px">${sorted.filter(i=>d.items[i]===v).length}</span></button>`).join('')}</div>`}
 else if(d.type==='puzzle'){const cols=puzzle.length===6?3:2,rows=puzzle.length/cols,col=d.target%4,row=Math.floor(d.target/4);body=`<p class="task-caption" style="text-align:center">Нажми на две части, чтобы поменять их местами.</p><div style="text-align:center">${art(d.target)}</div><div class="puzzle-board" style="grid-template-columns:repeat(${cols},1fr);aspect-ratio:${cols}/${rows}">${puzzle.map((v,i)=>`<button class="puzzle-piece ${pieceSelected===i?'selected':''} ${hinted&&v===i?'hint':''}" style="background-size:${cols*400}% ${rows*400}%;background-position:${(col*cols+v%cols)/(4*cols-1)*100}% ${(row*rows+Math.floor(v/cols))/(4*rows-1)*100}%" data-action="puzzle-piece" data-index="${i}" aria-label="Часть ${v+1}, место ${i+1}" ${success?'disabled':''}></button>`).join('')}</div>`}
 else if(d.type==='life'){body=`<p class="task-caption" style="text-align:center">${skillData[d.skill][0]}. Выбери действия по порядку.</p><div class="answers">${d.options.map(v=>`<button class="answer ${orderPicked.includes(v)?'correct':''} ${hinted&&v===orderPicked.length?'hint':''}" data-action="order" data-value="${v}" ${orderPicked.includes(v)||success?'disabled':''}>${art(d.stepsArt[v])}<span style="font-size:16px;max-width:180px;line-height:1.4">${d.steps[v]}</span>${orderPicked.includes(v)?`<span class="completed-mark">${v+1}</span>`:''}</button>`).join('')}</div>`}
 else {let example='';if(d.type==='count')example=`<div class="sequence">${Array.from({length:d.target},()=>art(1)).join('')}</div>`;if(d.type==='match')example=`<div class="sequence">${art(d.target)}<span class="question">?</span></div>`;if(d.type==='sequence')example=`<div class="sequence">${[...d.pair,...d.pair.slice(0,-1)].map(v=>art(v)).join('')}<span class="question">?</span></div>`;
 if(d.type==='sequence'){d.target=d.pair[d.pair.length-1];d.options=shuffled([d.target,...d.pair.filter(x=>x!==d.target),...shuffled([0,1,2,3,8,13,15].filter(x=>!d.pair.includes(x)),d.seed).slice(0,Math.max(0,d.n-d.pair.length))],d.seed+8)}
 body=example+`<div class="answers ${success?'answer-success':''}">${(success?[d.type==='choice'?chosenAnswer:d.target]:d.options).map((v,i)=>`<button class="answer ${hinted&&v===d.target?'hint':''} ${success&&(d.type==='choice'||v===d.target)?'correct':''}" data-action="answer" data-value="${v}" data-index="${i}" aria-label="${h(d.type==='color'?colors[v][0]+' кубик':d.type==='shape'?shapes[v][0]:d.type==='count'?v:d.type==='odd'?shapes[v][0]:objects[v]?.[0])}" ${success?'disabled':''}>${optionVisual(d,v)}${d.type==='choice'?`<span>${objects[v][0]}</span>`:''}</button>`).join('')}</div>`}
 return pageHead('Играем и узнаём','Можно не спешить. У тебя всё получится.')+`<section class="panel"><div class="task-head"><div><span class="eyebrow">${d.free?'Свободная игра':`День ${d.day} · Занятие ${d.index+1} из 8`}</span><h1 style="margin-top:8px">${title}</h1></div><button class="round" data-action="repeat" aria-label="Повторить инструкцию">${svg('sound')}</button></div>${body}<div class="feedback" role="status">${h(feedback)}</div>${success?`<div class="success-next"><button class="primary next-big" data-action="next-task">${d.free?'Играть ещё':'Дальше'}<span aria-hidden="true">➜</span></button><button class="secondary" data-action="nav" data-route="activities">К занятиям</button></div>`:`<div class="task-actions"><button class="secondary" data-action="hint">Помощь</button><button class="secondary" data-action="skip">Пропустить</button><button class="secondary" data-action="pause">Перерыв</button></div>`}</section>`}
function afterGameRender(){if(success)setTimeout(()=>$('#app [data-action="next-task"]')?.focus(),0)}
function win(message=''){success=true;feedback=message||`Молодец, ${state.name}! Ты справился!`;if(!gameData.free&&!state.completed[gameData.id]){state.completed[gameData.id]={day:gameData.day,type:gameData.type,date:today(),errors};state.history.push({title:getTaskTitle(gameData),date:today(),day:gameData.day,errors});state.history=state.history.slice(-500)}state.task=null;activeTask=null;persist();render();speak(feedback)}
function mistake(message=''){errors++;feedback=message||(state.feedback==='direct'?`Неправильно. ${state.name}, попробуй ещё раз.`:`${state.name}, попробуй ещё раз.`);if(errors>=2){hinted=true;feedback+=` ${state.name}, давай попробуем вместе.`}render();speak(feedback)}
function modal(html){$('#modal').innerHTML=`<div class="modal-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-label="Дополнительное окно"><button class="close" data-action="close" aria-label="Закрыть">×</button>${html}</section></div>`;setTimeout(()=>$('#modal button:not(.close),#modal input')?.focus(),0)}
function closeModal(){resetPending=false;if(mediaRecorder?.state==='recording')mediaRecorder.stop();recordStream?.getTracks().forEach(t=>t.stop());$('#modal').innerHTML=''}
function showGate(next='settings'){const a=2+Math.floor(Math.random()*4),b=3+Math.floor(Math.random()*5);window.gateAnswer=a+b;window.gateNext=next;modal(`<h2>Вход для родителей</h2><p class="settings-note">Попроси взрослого решить пример.</p><div class="speech-bubble">${a} + ${b} = ?</div><div class="gate">${shuffled([a+b,a+b+2,a+b-1],Date.now()%1000).map(v=>`<button class="secondary" data-action="gate-answer" data-value="${v}">${v}</button>`).join('')}</div>`)}
function showSettings(){const russian=voices.filter(v=>v.lang.startsWith('ru'));modal(`<h2>Настройки для родителей</h2><form id="settings-form"><div class="settings-grid"><label class="field">Имя ребёнка<input name="name" value="${h(state.name)}" required maxlength="30"></label><label class="field">Сложность<select name="level">${[['auto','Автоматически'],['2','Лёгкая · 2 варианта'],['3','Средняя · 3 варианта'],['4','Продвинутая · 4 варианта']].map(([v,l])=>`<option value="${v}" ${state.level===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field full">Голос на русском языке<select name="voice"><option value="">Системный русский голос</option>${russian.map(v=>`<option value="${h(v.voiceURI)}" ${state.voice===v.voiceURI?'selected':''}>${h(v.name)}${v.localService?' · на устройстве':''}</option>`).join('')}</select></label><label class="field">Скорость речи<input type="range" name="rate" min="0.5" max="1.2" step="0.05" value="${state.rate}"></label><label class="field">Громкость речи<input type="range" name="volume" min="0" max="1" step="0.1" value="${state.volume}"></label><label class="field">Яркость<input type="range" name="brightness" min="0.65" max="1.05" step="0.05" value="${state.brightness}"></label><label class="field">Контраст<input type="range" name="contrast" min="0.8" max="1.2" step="0.05" value="${state.contrast}"></label><label class="field">Размер подписей<input type="range" name="size" min="0.9" max="1.2" step="0.05" value="${state.size}"></label><label class="field">Обратная связь<select name="feedback"><option value="gentle" ${state.feedback==='gentle'?'selected':''}>Мягкая подсказка</option><option value="direct" ${state.feedback==='direct'?'selected':''}>Прямое «Нет, неправильно»</option></select></label><label class="toggle"><input name="speech" type="checkbox" ${state.speech?'checked':''}>Голосовые подсказки</label><label class="toggle"><input name="animation" type="checkbox" ${state.animation?'checked':''}>Плавные переходы</label></div><p class="audio-note">Музыки и звуковых эффектов нет. Озвучка использует установленные русские голоса Android. Для работы без интернета заранее загрузите русский голос в настройках синтеза речи устройства. ${russian.length?'Найдено русских голосов: '+russian.length+'.':'Русский голос пока не найден — проверьте настройки речи устройства.'}</p><div class="toolbar"><button class="primary" type="submit">Сохранить</button><button class="secondary" type="button" data-action="test-name">Прослушать имя</button></div></form><hr class="divider"><div class="toolbar"><button class="secondary" data-action="record-name">Записать имя своим голосом</button>${state.recording?'<button class="secondary" data-action="play-name">Послушать запись</button>':''}</div><p class="audio-note">Запись имени звучит по кнопке приветствия. Остальные фразы произносит выбранный голос.</p><hr class="divider"><div class="toolbar"><button class="secondary" data-action="edit-schedule">Изменить расписание</button><button class="secondary" data-action="custom-form">Добавить карточку</button><button class="secondary" data-action="manage-topics">Темы занятий</button></div><div class="toolbar"><button class="secondary" data-action="export">Резервная копия</button><label class="secondary" style="cursor:pointer">Восстановить<input type="file" id="restore-file" accept="application/json" hidden></label><button class="secondary" data-action="install">Установить приложение</button></div><hr class="divider"><h3>Программа на 60 дней</h3><p class="settings-note">Можно сбросить результаты и снова пройти все занятия с первого дня.</p><button class="secondary" data-action="reset-request">Начать заново</button><p class="settings-note">Данные сохраняются на этом устройстве. Для переноса на другое устройство используйте резервную копию. Камера и микрофон без вашего действия не включаются.</p>`)}
function showResetConfirmation(){modal(`<h2>Начать программу заново?</h2><p class="settings-note">Программа вернётся к первому дню. Будут сброшены результаты всех занятий, достижения, отметки освоенных навыков и выполненных дел.</p><p class="settings-note">Имя ребёнка, настройки, расписание и собственные карточки сохранятся. Если хотите сохранить текущие результаты, сначала скачайте резервную копию.</p><div class="task-actions"><button class="secondary" data-action="export">Скачать резервную копию</button><button class="secondary" data-action="close">Отмена</button><button class="primary" data-action="reset-confirm">Сбросить и начать с дня 1</button></div>`);resetPending=true}
function resetProgram(){const previous=state;state={...state,day:1,completed:{},skills:[],history:[],checked:{},task:null};if(!persist()){state=previous;return}activeTask=null;gameData=null;feedback='';hinted=false;errors=0;success=false;puzzle=[];pieceSelected=null;orderPicked=[];sortPicked=null;sorted=[];memoryHidden=false;closeModal();navigate('activities');toast('Готово! Можно снова проходить программу с первого дня.')}
function showSkill(i){const [title,,steps,arts]=skillData[i];modal(`<h2>Я могу ${h(title.toLowerCase())}</h2><div class="skill-steps">${steps.map((s,j)=>`<div class="step">${art(arts[j])}<b><span class="step-number">${j+1}</span>${s}</b></div>`).join('')}</div><div class="task-actions"><button class="primary" data-action="read-skill" data-index="${i}">Прослушать шаги</button><button class="secondary" data-action="gate-skill" data-index="${i}">${state.skills.includes(i)?'Освоено ✓ · изменить':'Для родителя: отметить навык'}</button></div>`)}
function showDays(){modal(`<h2>Выбери день</h2><p class="settings-note">Все дни открыты. Пройденные занятия можно повторять.</p><div class="days">${Array.from({length:Math.max(60,state.day)},(_,i)=>`<button class="day ${state.day===i+1?'active':''} ${doneDay(i+1)===8?'completed':''}" data-action="set-day" data-day="${i+1}">${i+1}${doneDay(i+1)===8?' ✓':''}</button>`).join('')}</div>`)}
function nextTask(skip=false){if(!gameData)return;const d=gameData;if(d.free){startTask({...d,seed:d.seed+79,id:'free-'+Date.now()});return}if(d.index<7){startTask(dayTasks(d.day)[d.index+1]);return}state.day=d.day+1;state.task=null;activeTask=null;persist();navigate('activities');modal(`<div class="finish">${art(7)}<h2>На сегодня всё, ${h(state.name)}!</h2><p>Ты можешь отдохнуть, выбрать другую игру или продолжить.</p><div class="task-actions"><button class="primary" data-action="close">Отлично</button>${d.day>=60?'<button class="secondary" data-action="reset-program">Для родителя: начать заново</button>':''}</div></div>`);speak(`${state.name}, можно отдохнуть или выбрать другую игру.`)}
const views={home:homeView,wants:()=>communicateView('wants'),emotions:()=>communicateView('emotions'),skills:skillsView,schedule:scheduleView,achievements:achievementsView,activities:activitiesView,game:gameView};
document.addEventListener('click',async e=>{const btn=e.target.closest('button,[data-action]');if(!btn)return;const a=btn.dataset.action,i=Number(btn.dataset.index),v=Number(btn.dataset.value);switch(a){
 case'quick-answer':speak(btn.dataset.answer);toast(btn.dataset.answer);break;
 case'toy-piece':if(Date.now()-lastToyDrag>300)selectToy(v);break;
 case'toy-place':placeToy(v);break;
 case'nav':navigate(btn.dataset.route);break;case'home':navigate('home');break;
 case'greet':if(state.recording){new Audio(state.recording).play().catch(()=>toast('Запись не удалось воспроизвести.'));}else speak(`Привет, ${state.name}! Что будем делать сегодня?`);break;
 case'say':{const list=btn.dataset.kind==='wants'?wants:emotions;const phrase=list[i][0];speak(phrase);toast(phrase);break}
 case'custom-say':{const c=state.custom[i];if(c.audio)new Audio(c.audio).play().catch(()=>speak(c.label));else speak(c.label);toast(c.label);break}
 case'gate':showGate();break;case'close':closeModal();break;
 case'gate-answer':if(v===window.gateAnswer){if(window.gateNext.startsWith('skill-')){const index=Number(window.gateNext.slice(6));state.skills=state.skills.includes(index)?state.skills.filter(x=>x!==index):[...state.skills,index];persist();closeModal();render();toast('Отметка навыка сохранена')}else if(window.gateNext==='reset-progress')showResetConfirmation();else showSettings()}else toast('Попробуйте ещё раз');break;
 case'task':closeModal();startTask(dayTasks(state.day)[i]);break;
 case'start-day':startTask(dayTasks(state.day).find(t=>!state.completed[t.id])||dayTasks(state.day)[0]);break;
 case'resume':if(activeTask)startTask(activeTask);break;
 case'free-game':startTask({type:btn.dataset.type,day:state.day,index:0,seed:Date.now()%200000,id:'free-'+Date.now(),free:true});break;
 case'choose-day':showDays();break;case'set-day':state.day=Number(btn.dataset.day);persist();closeModal();render();break;
 case'next-day':state.day++;persist();render();break;
 case'repeat':speak(`${state.name}, ${instruction(gameData).toLowerCase()}`);break;
 case'answer':if(!success){chosenAnswer=v;const correct=gameData.type==='choice'||(gameData.type==='odd'?i===gameData.oddPos:v===gameData.target);const message=explainAnswer(gameData,v,correct);if(correct)win(message);else mistake(message)}break;
 case'memory-hide':memoryHidden=true;render();speak(`${state.name}, какой предмет ты запомнил?`);break;
 case'hint':if(TOY_TYPES.includes(gameData.type)){toyHint();break}hinted=true;if(gameData.type==='memory'){memoryHidden=false;feedback='Посмотри на предмет ещё раз.'}else if(gameData.type==='puzzle'){feedback='Посмотри на образец. Начни с левого верхнего угла.'}else if(gameData.type==='sort'){feedback='Выбери кубик, затем корзинку такого же цвета.'}else if(gameData.type==='life'){feedback=gameData.steps[orderPicked.length]}else feedback='Нужный ответ выделен зелёной рамкой.';render();speak(`${state.name}, ${feedback}`);break;
 case'sort-pick':if(!success){sortPicked=i;render();speak(colors[gameData.items[i]][0]+' кубик. Выбери корзинку такого же цвета.')}break;
 case'sort-drop':if(!success&&sortPicked!==null){const name=colors[gameData.items[sortPicked]][0]+' кубик';if(gameData.items[sortPicked]===v){sorted.push(sortPicked);sortPicked=null;if(sorted.length===gameData.items.length)win('Правильно! '+name+' на месте. Все кубики разложены.');else{feedback='Правильно! '+name+' на месте. Выбери следующий кубик.';render();speak(feedback)}}else mistake('Это '+name+'. Эта корзинка другого цвета. Попробуй ещё раз.')}else if(!success){toast('Сначала выбери кубик');speak('Сначала выбери кубик')}break;
 case'puzzle-piece':if(success)break;if(pieceSelected===null){pieceSelected=i;render();speak('Часть '+(puzzle[i]+1)+'. Выбери другую часть, чтобы поменять их местами.')}else{[puzzle[pieceSelected],puzzle[i]]=[puzzle[i],puzzle[pieceSelected]];pieceSelected=null;if(puzzle.every((p,j)=>p===j))win('Правильно! Картинка собрана. Молодец, '+state.name+'!');else{feedback='Части поменялись местами. Посмотри на картинку.';render();speak(feedback)}}break;
 case'order':if(!success){if(v===orderPicked.length){orderPicked.push(v);if(orderPicked.length===3)win('Правильно! '+gameData.steps[v]+'. Все шаги по порядку.');else{feedback='Правильно. '+gameData.steps[v]+'. Что дальше?';render();speak(feedback)}}else mistake('Это действие будет позже. Сначала: '+gameData.steps[orderPicked.length]+'.')}break;
 case'next-task':nextTask();break;case'skip':nextTask(true);break;
 case'pause':speak('Можно отдохнуть. Продолжим, когда захочешь.');modal(`<div class="pause">${art(12)}<h2>Время отдохнуть</h2><p class="task-caption">Можно сделать перерыв на столько, сколько нужно.</p><div class="task-actions"><button class="primary" data-action="close">Продолжить</button><button class="secondary" data-action="pause-home">На главную</button></div></div>`);break;
 case'pause-home':closeModal();navigate('home');break;
 case'skill':showSkill(i);break;case'read-skill':speak(`${state.name}, ${skillData[i][0]}. ${skillData[i][2].join('. Затем ')}.`);break;case'gate-skill':showGate('skill-'+i);break;
 case'read-schedule':speak(`${state.name}, ${state.schedule[i][1]}`);break;
 case'schedule-check':{const arr=state.checked[today()]||[];state.checked[today()]=arr.includes(i)?arr.filter(v=>v!==i):[...arr,i];persist();render();break}
 case'test-name':{const f=$('#settings-form'),name=f?.elements.name.value||state.name;const old={...state};if(f){state.rate=Number(f.elements.rate.value);state.volume=Number(f.elements.volume.value);state.voice=f.elements.voice.value;state.speech=true}speak(`Привет, ${name}!`);state={...old};break}
 case'edit-schedule':showScheduleEditor();break;case'add-schedule':state.schedule.push(['12:00','Новое действие',13]);persist();showScheduleEditor();break;
 case'move-schedule':{const j=i+Number(btn.dataset.move);if(j>=0&&j<state.schedule.length){[state.schedule[i],state.schedule[j]]=[state.schedule[j],state.schedule[i]];state.checked={};persist();showScheduleEditor()}break}
 case'custom-form':showCustomForm();break;case'manage-topics':showTopics();break;
 case'delete-custom':state.custom.splice(i,1);persist();showCustomForm();render();break;
 case'export':{if(window.MoyMirNative){MoyMirNative.saveBackup(JSON.stringify({format:'moy-mir',version:1,state},null,2));break}const blob=new Blob([JSON.stringify({format:'moy-mir',version:1,state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='moy-mir-backup-'+today()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Резервная копия подготовлена');break}
 case'install':if(window.MoyMirNative){toast('Приложение уже установлено');break}if(pendingInstall){await pendingInstall.prompt();pendingInstall=null}else toast('В меню браузера выберите «Установить приложение» или «На экран Домой». Для работы офлайн сначала откройте приложение с интернетом.');break;
 case'record-name':await beginRecording();break;case'stop-recording':if(mediaRecorder?.state==='recording')mediaRecorder.stop();break;case'play-name':if(state.recording)new Audio(state.recording).play().catch(()=>toast('Не удалось воспроизвести запись'));break;
 case'reset-program':showGate('reset-progress');break;
 case'reset-request':showResetConfirmation();break;
 case'reset-confirm':if(resetPending)resetProgram();break;
 case'settings-back':resetPending=false;showSettings();break;
 }
 if(!ownSpeechActions.has(a))speakButton(btn,a);
});
function showScheduleEditor(){modal(`<h2>Расписание дня</h2><form id="schedule-form">${state.schedule.map(([time,name],i)=>`<div class="schedule-edit-row"><input type="time" name="time-${i}" value="${h(time)}" aria-label="Время действия ${i+1}" required><input name="label-${i}" value="${h(name)}" aria-label="Название действия ${i+1}" required maxlength="50"><button type="button" data-action="move-schedule" data-index="${i}" data-move="-1" aria-label="Переместить выше">↑</button><button type="button" data-action="move-schedule" data-index="${i}" data-move="1" aria-label="Переместить ниже">↓</button></div>`).join('')}<div class="toolbar"><button class="primary" type="submit">Сохранить расписание</button><button class="secondary" type="button" data-action="add-schedule">Добавить действие</button></div></form><p class="settings-note">Изменения времени и названий сохраняются по кнопке. Перестановка применяется сразу.</p><button class="secondary" data-action="settings-back">Назад к настройкам</button>`)}
