 if(f.id==='custom-form'){const image=data.get('image'),audio=data.get('audio');if(audio.size>1200000){toast('Выберите короткую запись размером до 1,2 МБ');return}try{const c={label:String(data.get('label')).trim(),image:await resizeImage(image),audio:audio.size?await readData(audio):null};state.custom.push(c);if(persist()){closeModal();navigate('wants');toast('Карточка добавлена')}else state.custom.pop()}catch(err){toast('Не удалось прочитать файл. Выберите другое изображение.')}}
 if(f.id==='topics-form'){if(!types.some(([id])=>data.has(id))){toast('Оставьте хотя бы одну тему');return}state.excluded=types.filter(([id])=>!data.has(id)).map(([id])=>id);persist();closeModal();render();toast('Темы сохранены')}
 if(f.id==='welcome-form'){const name=String(data.get('name')).trim();if(!name){toast('Напишите имя');return}state.name=name;state.onboarded=true;persist();closeModal();render()}
