document.addEventListener('change',async e=>{if(e.target.id==='restore-file'){const file=e.target.files[0];if(!file)return;try{const json=JSON.parse(await file.text());if(json.format!=='moy-mir'||json.version!==1||!json.state||!Array.isArray(json.state.schedule)||!Array.isArray(json.state.custom)||typeof json.state.name!=='string'||!json.state.completed)throw Error('format');window.restoreCandidate=json.state;modal(`<h2>Восстановить резервную копию?</h2><p class="settings-note">Настройки и прогресс на этом устройстве будут заменены данными из файла для ${h(json.state.name)}. Выполнено занятий: ${Object.keys(json.state.completed).length}.</p><button class="primary" id="restore-confirm">Восстановить</button>`);$('#restore-confirm').onclick=()=>{state={...state,...window.restoreCandidate};state.custom=state.custom.filter(c=>typeof c.label==='string'&&/^data:image\//.test(c.image)&&(!c.audio||/^data:audio\//.test(c.audio)));state.recording=typeof state.recording==='string'&&/^data:audio\//.test(state.recording)?state.recording:null;state.brightness=Math.max(.65,Math.min(1.05,Number(state.brightness)||1));state.contrast=Math.max(.8,Math.min(1.2,Number(state.contrast)||1));state.size=Math.max(.9,Math.min(1.2,Number(state.size)||1));activeTask=null;state.task=null;persist();closeModal();navigate('home');toast('Данные восстановлены')};}catch(err){toast('Файл не подходит. Выберите резервную копию «Мой мир».')}}});
async function beginRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Запись недоступна на этом устройстве');return}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];mediaRecorder=new MediaRecorder(recordStream);mediaRecorder.ondataavailable=e=>recordChunks.push(e.data);mediaRecorder.onstop=async()=>{const b=new Blob(recordChunks,{type:mediaRecorder.mimeType});state.recording=await readData(b);recordStream.getTracks().forEach(t=>t.stop());persist();if($('#modal').innerHTML)showSettings();toast('Запись имени сохранена')};mediaRecorder.start();modal(`<h2>Произнесите имя ребёнка</h2><p class="settings-note">Например: «Привет, ${h(state.name || 'имя ребёнка')}!»</p><button class="primary" data-action="stop-recording">Остановить запись</button>`);setTimeout(()=>{if(mediaRecorder?.state==='recording')mediaRecorder.stop()},10000)}catch(err){toast('Микрофон недоступен. Проверьте разрешение браузера.')}}
