document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal').innerHTML)closeModal();if(e.key==='Tab'&&$('#modal').innerHTML){const focusable=[...$('#modal').querySelectorAll('button,input,select,a')].filter(el=>!el.disabled&&!el.hidden),first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
let toyState=null,chosenAnswer=null,lastToyDrag=0,toyDrag=null;
const objectNames=['стакан','яблоко','кубики','машинка','сердечко','галочка','календарь','кубок','цветочек','деталь пазла','фигуры','душ','подушка','звёздочка','облачко','дерево'];
const shapeNames=['круг','квадрат','треугольник','звезда','прямоугольник'];
const ringNames=['самое большое кольцо','большое кольцо','среднее кольцо','маленькое кольцо'];
const ownSpeechActions=new Set(['greet','say','custom-say','task','start-day','resume','free-game','repeat','answer','memory-hide','hint','sort-pick','sort-drop','puzzle-piece','order','next-task','skip','pause','read-skill','read-schedule','test-name','quick-answer','toy-piece','toy-place','record-name','stop-recording','play-name']);
function speakButton(btn,action){let label=btn.querySelector?.('.tile-title')?.textContent||btn.getAttribute?.('aria-label')||btn.textContent||'';if(action==='set-day')label='День '+btn.dataset.day;if(action==='nav')label=sections.find(s=>s[0]===btn.dataset.route)?.[1]||label;if(label.trim())speak(label.trim())}
function answerName(d,v){if(d.type==='color')return colors[v][0]+' кубик';if(d.type==='shape'||d.type==='odd')return shapeNames[v];if(d.type==='count')return v+' '+(v===1?'яблоко':v>=2&&v<=4?'яблока':'яблок');return objectNames[v]}
function explainAnswer(d,v,correct){const selected=answerName(d,v),target=answerName(d,d.target);if(d.type==='choice')return `Ты выбрал: ${selected}. Твой выбор принят, ${state.name}.`;if(correct){if(d.type==='count')return `Правильно! Здесь ${selected}. Молодец, ${state.name}!`;if(d.type==='odd')return `Правильно! Это ${selected}. Эта фигура отличается от остальных.`;return `Правильно, это ${selected}. Молодец, ${state.name}!`}const prefix=state.feedback==='direct'?'Неправильно. ':'';if(d.type==='count')return `${prefix}Здесь не ${selected}. Давай посчитаем ещё раз.`;if(d.type==='odd')return `${prefix}Это ${selected}. Эта фигура такая же, как остальные. Найди ту, которая отличается.`;return `${prefix}Это не ${target}. Это ${selected}. ${state.name}, попробуй ещё раз.`}
function initializeToy(d){chosenAnswer=null;toyState=null;if(!TOY_TYPES.includes(d.type))return;const n=level(d)===2?3:4,cs=shuffled([0,1,2,3,4],d.seed);toyState={selected:null,placed:[],count:n,colors:cs,pieces:shuffled([...Array(n).keys()],d.seed+3)};if(d.type==='sorter'){toyState.count=4;toyState.pieces=shuffled([0,1,2,3],d.seed)}if(d.type==='beads'){toyState.pattern=Array.from({length:n+2},(_,i)=>cs[i%2]);toyState.pieces=cs.slice(0,level(d)===2?2:3);toyState.count=toyState.pattern.length}}
function toyIcon(type){if(type==='pyramid')return '<span class="toy-mini mini-pyramid" aria-hidden="true"><i></i><b></b><b></b><b></b></span>';if(type==='tower')return '<span class="toy-mini mini-tower" aria-hidden="true"><b></b><b></b><b></b></span>';if(type==='beads')return '<span class="toy-mini mini-beads" aria-hidden="true"><b></b><b></b><b></b></span>';return '<span class="toy-mini mini-sorter" aria-hidden="true"><b></b><b></b><b></b></span>'}
function taskVisual(t){return TOY_TYPES.includes(t.type)?toyIcon(t.type):art(taskArt(t))}
function toyColor(id){return colors[toyState.colors[id%toyState.colors.length]][1]}
function toyName(id){if(gameData.type==='sorter')return shapeNames[id];if(gameData.type==='pyramid')return ringNames[id];if(gameData.type==='tower')return colors[toyState.colors[id]][0]+' кубик';return colors[id][0]+' бусина'}
function toyVisual(id,type=gameData.type,small=false){const c=type==='beads'?colors[id][1]:toyColor(id);if(type==='sorter')return `<span class="toy-solid ts-${shapes[id][1]}" style="--toy-color:${c}" aria-hidden="true"></span>`;if(type==='pyramid')return `<span class="toy-ring" style="--toy-color:${c};--ring-width:${(small?160:148)-id*26}px" aria-hidden="true"></span>`;if(type==='tower')return `<span class="toy-cube" style="--toy-color:${c}" aria-hidden="true"></span>`;return `<span class="toy-bead" style="--toy-color:${c}" aria-hidden="true"></span>`}
function toyView(d){if(!toyState)initializeToy(d);const t=toyState;let stage='';
 if(d.type==='sorter')stage=`<div class="sorter-board">${[0,1,2,3].map(id=>`<button class="toy-target sorter-slot ${hinted&&t.selected===id?'hint':''}" data-action="toy-place" data-value="${id}" data-toy-target="${id}" aria-label="Окошко: ${shapeNames[id]}" ${success?'disabled':''}>${t.placed.includes(id)?toyVisual(id):`<span class="toy-solid ts-${shapes[id][1]} slot-shadow" aria-hidden="true"></span>`}</button>`).join('')}</div>`;
 if(d.type==='pyramid')stage=`<button class="toy-target pyramid-stage ${hinted?'hint':''}" data-action="toy-place" data-value="0" data-toy-target="0" aria-label="Положить кольцо на штырёк" ${success?'disabled':''}><span class="pyramid-rod"></span><span class="pyramid-base"></span><span class="pyramid-stack">${t.placed.map(id=>toyVisual(id,'pyramid',true)).join('')}</span></button>`;
 if(d.type==='tower')stage=`<div class="tower-reference" aria-label="Образец башни"><span>Образец</span><div>${[...Array(t.count).keys()].reverse().map(id=>toyVisual(id,'tower',true)).join('')}</div></div><button class="toy-target tower-stage ${hinted?'hint':''}" data-action="toy-place" data-value="0" data-toy-target="0" aria-label="Поставить кубик на башню" ${success?'disabled':''}><span class="tower-base"></span><span class="tower-stack">${t.placed.map(id=>toyVisual(id,'tower',true)).join('')}</span></button>`;
 if(d.type==='beads')stage=`<div class="bead-reference" aria-label="Образец бус"><span>Собери так же</span><div>${t.pattern.map(id=>toyVisual(id,'beads',true)).join('')}</div></div><div class="bead-string">${t.pattern.map((id,i)=>`<button class="toy-target bead-slot ${hinted&&i===t.placed.length?'hint':''}" data-action="toy-place" data-value="${i}" data-toy-target="${i}" aria-label="Место для бусины ${i+1}" ${t.placed.length>i||success?'disabled':''}>${i<t.placed.length?toyVisual(t.placed[i],'beads'):''}</button>`).join('')}</div>`;
 const ids=t.pieces.filter(id=>d.type==='beads'||!t.placed.includes(id));
 return `<p class="task-caption toy-instruction">${d.type==='sorter'?'Найди для каждой фигуры такое же окошко.':d.type==='pyramid'?'Собирай от самого большого кольца к маленькому.':d.type==='tower'?'Построй башню снизу вверх, как на образце.':'Нанизывай бусины слева направо, как на образце.'}</p><div class="toy-stage ${d.type}">${stage}</div>${success?'':`<p class="toy-method">Перетащи деталь или нажми на неё, а затем на место для неё.</p><div class="toy-tray">${ids.map(id=>`<button class="toy-piece ${t.selected===id?'selected':''} ${hinted&&toyExpected()===id?'hint':''}" data-action="toy-piece" data-value="${id}" data-toy-piece="${id}" aria-label="${h(toyName(id))}" aria-pressed="${t.selected===id}">${toyVisual(id)}</button>`).join('')}</div>`}<div class="toy-counter">Готово: ${t.placed.length} из ${t.count}</div>`
}
function toyExpected(){if(!toyState)return null;if(gameData.type==='sorter')return [0,1,2,3].find(id=>!toyState.placed.includes(id));if(gameData.type==='beads')return toyState.pattern[toyState.placed.length];return toyState.placed.length}
function selectToy(id,announce=true){if(success||!toyState||!toyState.pieces.includes(id))return;if(gameData.type!=='beads'&&toyState.placed.includes(id))return;toyState.selected=id;feedback='';render();if(announce)speak(`${toyName(id)}. ${gameData.type==='sorter'?'Найди такое же окошко.':gameData.type==='pyramid'?'Положи кольцо на штырёк.':gameData.type==='tower'?'Поставь кубик на башню.':'Положи бусину на ниточку.'}`)}
function placeToy(target){if(success||!toyState)return;const t=toyState,id=t.selected;if(id===null){feedback='Сначала выбери деталь.';render();speak(feedback);return}let good=false;
 if(gameData.type==='sorter')good=id===target&&!t.placed.includes(id);
 else if(gameData.type==='beads')good=target===t.placed.length&&id===t.pattern[target];
 else good=id===t.placed.length;
 if(!good){const expected=gameData.type==='sorter'?shapeNames[id]:toyName(toyExpected());mistake((state.feedback==='direct'?'Неправильно. ':'')+(gameData.type==='sorter'?`Это окошко не подходит. Найди окошко: ${expected}.`:gameData.type==='beads'&&target!==t.placed.length?'Сначала заполним следующее пустое место слева.':`Сейчас нужно ${expected}. Попробуй ещё раз.`));return}
 const name=toyName(id);t.placed.push(id);t.selected=null;hinted=false;
 if(t.placed.length===t.count){win(`Правильно! ${name} на месте. ${gameData.type==='sorter'?'Все фигурки нашли свои окошки.':gameData.type==='pyramid'?'Пирамидка собрана.':gameData.type==='tower'?'Башня построена.':'Бусы собраны.'} Молодец, ${state.name}!`)}else{feedback=`Правильно! ${name} на месте. Возьми следующую деталь.`;render();speak(feedback)}
}
function toyHint(){hinted=true;const id=toyExpected();feedback=`Давай вместе. Возьми ${gameData.type==='sorter'?shapes[id][0]:toyName(id)}.`;render();speak(feedback)}
document.addEventListener('pointerdown',e=>{const el=e.target.closest?.('[data-toy-piece]');if(!el||route!=='game'||success)return;toyDrag={id:Number(el.dataset.toyPiece),el,x:e.clientX,y:e.clientY,pointer:e.pointerId,ghost:null};el.setPointerCapture?.(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!toyDrag||toyDrag.pointer!==e.pointerId)return;const d=toyDrag;if(!d.ghost&&Math.hypot(e.clientX-d.x,e.clientY-d.y)>9){d.ghost=d.el.cloneNode(true);d.ghost.classList.add('toy-drag-ghost');const rect=d.el.getBoundingClientRect();d.ghost.style.width=rect.width+'px';d.ghost.style.height=rect.height+'px';document.body.appendChild(d.ghost)}if(d.ghost){e.preventDefault();d.ghost.style.left=e.clientX+'px';d.ghost.style.top=e.clientY+'px'}},{passive:false});
document.addEventListener('pointerup',e=>{if(!toyDrag||toyDrag.pointer!==e.pointerId)return;const d=toyDrag;toyDrag=null;d.el.releasePointerCapture?.(e.pointerId);if(!d.ghost)return;lastToyDrag=Date.now();d.ghost.remove();const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-toy-target]');selectToy(d.id,false);if(target)placeToy(Number(target.dataset.toyTarget));else{speak(toyName(d.id)+'. Перенеси деталь на игровое поле.')}});
document.addEventListener('pointercancel',()=>{toyDrag?.ghost?.remove();toyDrag=null});

